python3 - <<'EOF'
from duration import parse_duration

valid = {
    "1h30m": 5400, " 2d 4h ": 187200, "1.5h": 5400,
    "1w2d3h4m5s": 788645, "1:02:03": 3723, "-45s": -45, "0": 0,
    "1h 30m": 5400, "1.5m": 90, "0.1h": 360, "05m": 300,
    "1:30": 90, "1:00:00": 3600, "90:00": 5400, "-1:30": -90,
    "-0s": 0, "0.0s": 0, "1.25s": None, "1w": 604800,
}
for k, v in valid.items():
    if v is None: continue
    got = parse_duration(k)
    assert got == v, (k, got, v)

invalid = ["", "   ", ".5h", "5.h", "30m1h", "1h1h", "1 h", "1h  30m",
           "0.3s", "1:60", "1:5", "+1h", "-", "5", "1.5", "1H", "1h,30m",
           "1h\t30m", "-0", "1:2:3", "1::30", "--1h", "1h 30m ", "0x10s"]
for k in invalid:
    try:
        r = parse_duration(k)
    except ValueError:
        pass
    else:
        raise AssertionError((k, r))

for bad in [None, 5, 1.0, b"1h", ["1h"]]:
    try:
        parse_duration(bad)
    except TypeError:
        pass
    else:
        raise AssertionError(bad)

print("all ok")
EOF

